changeSet.sql:
CREATE TABLE legislacao_trecho (
    id              UUID          PRIMARY KEY,
    content         TEXT          NOT NULL,
    metadata        JSON          NOT NULL,
    embedding       vector(1024)  NOT NULL,
    hash            TEXT GENERATED ALWAYS AS (metadata ->> 'hash') STORED,
    norma           TEXT GENERATED ALWAYS AS (metadata ->> 'norma') STORED,
    dispositivo     TEXT GENERATED ALWAYS AS (metadata ->> 'dispositivo') STORED,
    vigencia_inicio TEXT GENERATED ALWAYS AS (metadata ->> 'vigenciaInicio') STORED,
    vigencia_fim    TEXT GENERATED ALWAYS AS (metadata ->> 'vigenciaFim') STORED,
    conteudo_tsv    TSVECTOR GENERATED ALWAYS AS
                        (to_tsvector('portuguese', content)) STORED
);
CREATE UNIQUE INDEX uk_legislacao_trecho_hash ON legislacao_trecho (hash);
CREATE INDEX idx_legislacao_trecho_embedding
    ON legislacao_trecho USING hnsw (embedding vector_cosine_ops);
CREATE INDEX idx_legislacao_trecho_tsv ON legislacao_trecho USING gin (conteudo_tsv);
CREATE INDEX idx_legislacao_trecho_dispositivo
    ON legislacao_trecho (norma, dispositivo, vigencia_fim);
